const W=8*16,H=8;const px=new Array(W*H).fill(0);for(let c=0;c<16;c++){for(let y=0;y<8;y++){const b=bytes[c*8+y];for(let x=0;x<8;x++){px[y*W+c*8+x]=(b>>(7-x))&1;}}}
return {kind:"bitmap",width:W,height:H,pixels:px,palette:["#000","#fff"]};

// chars in a grid: COLS chars per row
const COLS=16;
const n=Math.floor(bytes.length/8);
const rows=Math.ceil(n/COLS);
const W=COLS*8,H=rows*8;
const px=new Array(W*H).fill(0);
for(let c=0;c<n;c++){const gx=(c%COLS)*8,gy=Math.floor(c/COLS)*8;
 for(let y=0;y<8;y++){const b=bytes[c*8+y];for(let x=0;x<8;x++)px[(gy+y)*W+gx+x]=(b>>(7-x))&1;}}
return {kind:"bitmap",width:W,height:H,pixels:px,palette:["#000000","#ffffff"]};

const base = params.base;
const lines=[];
const PG=256;
for(let p=0;p*PG<bytes.length;p++){
  const a=base+p*PG, sl=bytes.slice(p*PG,p*PG+PG);
  let zero=0,ff=0,lt40=0,hist=new Array(256).fill(0);
  for(const b of sl){ if(b===0)zero++; if(b===255)ff++; if(b<0x40)lt40++; hist[b]++; }
  let distinct=0; for(const h of hist) if(h)distinct++;
  // 64-byte structure: is byte 63 of each block 0 or equal across blocks?
  let s63=0; for(let k=0;k<4;k++) if(sl[k*64+63]===0) s63++;
  // sprite-likeness: rows of 3 bytes, count blocks where trailing byte 63 is 0
  // char-likeness: bytes 0 and 7 of each 8-byte group often 0 (top/bottom blank)
  let c0=0,c7=0; for(let k=0;k<32;k++){ if(sl[k*8]===0)c0++; if(sl[k*8+7]===0)c7++; }
  lines.push(
    "$"+a.toString(16).toUpperCase().padStart(4,"0")
    +"  zero="+String(zero).padStart(3)
    +" ff="+String(ff).padStart(3)
    +" <40="+String(lt40).padStart(3)
    +" distinct="+String(distinct).padStart(3)
    +" b63z="+s63+"/4"
    +" c0z="+String(c0).padStart(2)+"/32"
    +" c7z="+String(c7).padStart(2)+"/32");
}
return {kind:"text",lines};

