const sc=c=>{ c&=0x7f;
 if(c===0x20)return " ";
 if(c>=1&&c<=26)return String.fromCharCode(64+c);
 if(c>=0x30&&c<=0x39)return String.fromCharCode(c);
 if(c===0)return "@";
 return "·";};
const lines=[];
const n=Math.floor(bytes.length/200);
for(let w=0;w<n;w++){
 const b=bytes.slice(w*200,w*200+200);
 let t="";for(let i=160;i<200;i++)t+=sc(b[i]);
 const par=[]; for(let i=152;i<160;i++)par.push(b[i].toString(16).padStart(2,"0"));
 lines.push("wave "+String(w).padStart(2)+" @$"+(params.base+w*200).toString(16).toUpperCase()+"  params["+par.join(" ")+"]  |"+t+"|");
}
return {kind:"text",lines};

